mapper.select:
SELECT h.id, h.title, h.description, h.class_id, h.course_id, h.teacher_id, h.publish_time, h.deadline, h.create_time, h.update_time, h.is_deleted, cl.class_name, co.course_name, t.name AS teacher_name, (SELECT COUNT(*) FROM homework_submission hs WHERE hs.homework_id = h.id AND hs.is_deleted = 0 AND hs.status IN (2, 3)) AS submit_count, (SELECT COUNT(*) FROM homework_submission hs WHERE hs.homework_id = h.id AND hs.is_deleted = 0) AS total_count FROM homework h LEFT JOIN `class` cl ON h.class_id = cl.id AND cl.is_deleted = 0 LEFT JOIN course co ON h.course_id = co.id AND co.is_deleted = 0 LEFT JOIN teacher t ON h.teacher_id = t.id AND t.is_deleted = 0 WHERE h.is_deleted = 0
AND h.class_id = #{classId}
AND h.course_id = #{courseId}
ORDER BY h.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM homework h
WHERE h.is_deleted = 0

    AND h.class_id = #{classId}


    AND h.course_id = #{courseId}
